const ALL = FOLDERS.flatMap(f => f.subs.flatMap(s => s.posts))
const byId = Object.fromEntries(ALL.map(p => [p.id, p]))
export const allPosts = () => ALL.slice()
export const postById = id => byId[id] || null
export const folderById = id => FOLDERS.find(f => f.id === id) || null
export const subById = sid => { for (const f of FOLDERS) { const s = f.subs.find(x => x.id === sid); if (s) return s } return null }
export const leadPost = fid => { const f = folderById(fid); return f ? f.subs[0].posts[0] : null }
export function allTags() { const m = new Map(); ALL.forEach(p => p.tags.forEach(t => m.set(t,(m.get(t)||0)+1))); return [...m.entries()].sort((a,b)=>b[1]-a[1]).map(([tag,count])=>({tag,count})) }
export const postsByTag = tag => ALL.filter(p => p.tags.includes(tag))
export const backlinksOf = id => ALL.filter(p => p.links.includes(id))
export const recentPosts = (n=6) => ALL.slice().sort((a,b)=>a.days-b.days).slice(0,n)
export function searchPosts(q){ q=(q||'').trim().toLowerCase(); if(!q) return []; return ALL.filter(p=> p.title.toLowerCase().includes(q)||p.summary.toLowerCase().includes(q)||p.tags.some(t=>t.toLowerCase().includes(q))||p.folderName.toLowerCase().includes(q)||(p.md||'').toLowerCase().includes(q)).slice(0,14) }
export function localGraph(id){ const c=byId[id]; if(!c) return {nodes:[],edges:[]}; const ids=new Set([id,...c.links,...backlinksOf(id).map(p=>p.id)]); const nodes=[...ids].map(x=>byId[x]).filter(Boolean).map(p=>({id:p.id,title:p.title,hue:p.hue,center:p.id===id})); const edges=[]; nodes.forEach(n=>byId[n.id].links.forEach(t=>{if(ids.has(t))edges.push([n.id,t])})); return {nodes,edges} }
export const resolveLink = t => LINKINDEX[String(t||'').toLowerCase().trim().replace(/\s+/g,' ')] || null
